<?php
namespace App\Http\Controllers\Api\V1;
use App\Http\Controllers\Controller;
use App\Models\{TeacherProfile,User};
use App\Support\CurrentSchool;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Hash;
use Illuminate\Validation\Rule;
class TeacherController extends Controller {
 private function authorizeManager(Request $r):void{abort_unless(in_array($r->user()->role,['school_admin','super_admin'],true),403,'ليست لديك صلاحية إدارة المعلمين.');}
 public function index(Request $r){$this->authorizeManager($r);$q=TeacherProfile::with('user:id,name,email,phone,is_active')->where('school_id',CurrentSchool::id());if($r->filled('search')){$s=$r->string('search');$q->where(fn($x)=>$x->where('employee_number','like','%'.$s.'%')->orWhere('specialization','like','%'.$s.'%')->orWhereHas('user',fn($u)=>$u->where('name','like','%'.$s.'%')));}return $q->orderByDesc('id')->paginate(min((int)$r->input('per_page',20),100));}
 public function store(Request $r){$this->authorizeManager($r);$d=$r->validate(['name'=>'required|string|max:190','email'=>'nullable|email|max:190|unique:users,email','phone'=>'nullable|string|max:30','password'=>'required|string|min:8|max:100','employee_number'=>'nullable|string|max:60','specialization'=>'nullable|string|max:120','qualification'=>'nullable|string|max:190','hire_date'=>'nullable|date','bio'=>'nullable|string']);return DB::transaction(function()use($d){$u=User::create(['name'=>$d['name'],'email'=>$d['email']??null,'phone'=>$d['phone']??null,'password'=>Hash::make($d['password']),'role'=>'teacher','is_active'=>true]);$t=TeacherProfile::create(['school_id'=>CurrentSchool::id(),'user_id'=>$u->id,'employee_number'=>$d['employee_number']??('TCH-'.str_pad((string)$u->id,5,'0',STR_PAD_LEFT)),'specialization'=>$d['specialization']??null,'qualification'=>$d['qualification']??null,'hire_date'=>$d['hire_date']??now()->toDateString(),'phone'=>$d['phone']??null,'bio'=>$d['bio']??null]);return response()->json(['message'=>'تم إنشاء حساب المعلم بنجاح.','teacher'=>$t->load('user')],201);});}
 public function show(Request $r,int $id){$this->authorizeManager($r);return TeacherProfile::with(['user','assignments.gradeSubject.subject','assignments.classroom'])->where('school_id',CurrentSchool::id())->findOrFail($id);}
 public function update(Request $r,int $id){$this->authorizeManager($r);$t=TeacherProfile::where('school_id',CurrentSchool::id())->with('user')->findOrFail($id);$d=$r->validate(['name'=>'sometimes|required|string|max:190','email'=>['nullable','email','max:190',Rule::unique('users','email')->ignore($t->user_id)],'phone'=>'nullable|string|max:30','employee_number'=>['sometimes','required','string','max:60',Rule::unique('teacher_profiles','employee_number')->ignore($t->id)],'specialization'=>'nullable|string|max:120','qualification'=>'nullable|string|max:190','hire_date'=>'nullable|date','bio'=>'nullable|string','status'=>'sometimes|in:active,suspended,archived']);return DB::transaction(function()use($t,$d){$t->update(collect($d)->only(['employee_number','specialization','qualification','hire_date','bio','status'])->all());$t->user->update(collect($d)->only(['name','email','phone'])->all());if(($d['status']??null)==='archived')$t->user->update(['is_active'=>false]);return response()->json(['message'=>'تم تحديث بيانات المعلم.','teacher'=>$t->fresh()->load('user')]);});}
 public function destroy(Request $r,int $id){$this->authorizeManager($r);$t=TeacherProfile::where('school_id',CurrentSchool::id())->with('user')->findOrFail($id);$t->update(['status'=>'archived']);$t->user->update(['is_active'=>false]);return response()->json(['message'=>'تمت أرشفة المعلم مع الاحتفاظ بسجله.']);}
}
